// Clock group working status
namespace CLOCK_GROUP1_STATUS0_fields_ {

  enum class eOFF : std::uint32_t {
    // Clock is running.
    eOFF_0 = 0,
    // Turn off clock.
    eOFF_1 = 1,
  };

  enum class ePOWERDOWN : std::uint32_t {
    // Clock root is running
    eRUN = 0,
    // Clock root is Powered Down
    ePWRDWN = 1,
  };

  enum class eSLICE_BUSY : std::uint32_t {
    // Clock generation logic is not busy
    eDIS = 0,
    // Clock generation logic is applying the new setting
    eENABLE = 1,
  };

  enum class eUPDATE_FORWARD : std::uint32_t {
    // Synchronization not in process
    eDIS = 0,
    // Synchronization in process
    eENABLE = 1,
  };

  enum class eUPDATE_REVERSE : std::uint32_t {
    // Synchronization not in process
    eDIS = 0,
    // Synchronization in process
    eENABLE = 1,
  };

  enum class eCHANGING : std::uint32_t {
    // Clock root is not updating currently
    eDIS = 0,
    // Clock root logic is updating currently
    eENABLE = 1,
  };
  // Clock divider
  using DIV0 = ftl::mmio::Field<4, 0, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
  // Clock divider
  using RSTDIV = ftl::mmio::Field<8, 16, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
  // OFF
  using OFF = ftl::mmio::Field<1, 24, eOFF, ftl::mmio::RW, ftl::mmio::Normal>;
  // Current clock root POWERDOWN setting
  using POWERDOWN = ftl::mmio::Field<1, 27, ePOWERDOWN, ftl::mmio::RO, ftl::mmio::Normal>;
  // Internal updating in generation logic
  using SLICE_BUSY = ftl::mmio::Field<1, 28, eSLICE_BUSY, ftl::mmio::RO, ftl::mmio::Normal>;
  // Internal status synchronization to clock generation logic
  using UPDATE_FORWARD = ftl::mmio::Field<1, 29, eUPDATE_FORWARD, ftl::mmio::RO, ftl::mmio::Normal>;
  // Internal status synchronization from clock generation logic
  using UPDATE_REVERSE = ftl::mmio::Field<1, 30, eUPDATE_REVERSE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Internal updating in clock group
  using CHANGING = ftl::mmio::Field<1, 31, eCHANGING, ftl::mmio::RO, ftl::mmio::Normal>;
}  // namespace CLOCK_GROUP1_STATUS0_fields_

