// Clock group low power/extend status
namespace CLOCK_GROUP1_STATUS1_fields_ {

  enum class eDOWN_REQUEST : std::uint32_t {
    // No handshake signal is not requested
    eNOTREQ = 0,
    // Handshake signal with GPC status indicating frequency decrease is requested
    eREQUEST = 1,
  };

  enum class eDOWN_DONE : std::uint32_t {
    // Handshake signal with GPC status indicating frequency decrease is not complete
    eDISABLE = 0,
    // Handshake signal with GPC status indicating frequency decrease is complete
    eCOMPL = 1,
  };

  enum class eUP_REQUEST : std::uint32_t {
    // No handshake signal is not requested
    eNOTREQ = 0,
    // Handshake signal with GPC status indicating frequency increase is requested
    eREQUEST = 1,
  };

  enum class eUP_DONE : std::uint32_t {
    // Handshake signal with GPC status indicating frequency increase is not complete
    eDISABLE = 0,
    // Handshake signal with GPC status indicating frequency increase is complete
    eCOMPL = 1,
  };
  // Next Setpoint to change to
  using TARGET_SETPOINT = ftl::mmio::Field<4, 16, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  // Current Setpoint
  using CURRENT_SETPOINT = ftl::mmio::Field<4, 20, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock frequency decrease request
  using DOWN_REQUEST = ftl::mmio::Field<1, 24, eDOWN_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock frequency decrease complete
  using DOWN_DONE = ftl::mmio::Field<1, 25, eDOWN_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock frequency increase request
  using UP_REQUEST = ftl::mmio::Field<1, 26, eUP_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock frequency increase complete
  using UP_DONE = ftl::mmio::Field<1, 27, eUP_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
}  // namespace CLOCK_GROUP1_STATUS1_fields_

