// LPCG low power status
namespace LPCG40_STATUS1_fields_ {

  enum class eCPU0_MODE : std::uint32_t {
    // Run
    eRUN = 0,
    // Wait
    eWAIT = 1,
    // Stop
    eSTOP = 2,
    // Suspend
    eSUSPEND = 3,
  };

  enum class eCPU0_MODE_REQUEST : std::uint32_t {
    // No request
    eDIS = 0,
    // Request from domain to enter Low Power Mode
    eENABLE = 1,
  };

  enum class eCPU0_MODE_DONE : std::uint32_t {
    // Clock is not gated
    eDIS = 0,
    // Clock is gated-off
    eENABLE = 1,
  };

  enum class eCPU1_MODE : std::uint32_t {
    // Run
    eRUN = 0,
    // Wait
    eWAIT = 1,
    // Stop
    eSTOP = 2,
    // Suspend
    eSUSPEND = 3,
  };

  enum class eCPU1_MODE_REQUEST : std::uint32_t {
    // No request
    eDIS = 0,
    // Request from domain to enter Low Power Mode
    eENABLE = 1,
  };

  enum class eCPU1_MODE_DONE : std::uint32_t {
    // Clock is not gated
    eDIS = 0,
    // Clock is gated-off
    eENABLE = 1,
  };

  enum class eCPU2_MODE : std::uint32_t {
    // Run
    eRUN = 0,
    // Wait
    eWAIT = 1,
    // Stop
    eSTOP = 2,
    // Suspend
    eSUSPEND = 3,
  };

  enum class eCPU2_MODE_REQUEST : std::uint32_t {
    // No request
    eDIS = 0,
    // Request from domain to enter Low Power Mode
    eENABLE = 1,
  };

  enum class eCPU2_MODE_DONE : std::uint32_t {
    // Clock is not gated
    eDIS = 0,
    // Clock is gated-off
    eENABLE = 1,
  };

  enum class eCPU3_MODE : std::uint32_t {
    // Run
    eRUN = 0,
    // Wait
    eWAIT = 1,
    // Stop
    eSTOP = 2,
    // Suspend
    eSUSPEND = 3,
  };

  enum class eCPU3_MODE_REQUEST : std::uint32_t {
    // No request
    eDIS = 0,
    // Request from domain to enter Low Power Mode
    eENABLE = 1,
  };

  enum class eCPU3_MODE_DONE : std::uint32_t {
    // Clock is not gated
    eDIS = 0,
    // Clock is gated-off
    eENABLE = 1,
  };

  enum class eSETPOINT_OFF_REQUEST : std::uint32_t {
    // No request
    eDIS = 0,
    // Clock gate requested to be turned off
    eENABLE = 1,
  };

  enum class eSETPOINT_OFF_DONE : std::uint32_t {
    // Clock gate is not turned off
    eDIS = 0,
    // Clock gate is turned off
    eENABLE = 1,
  };

  enum class eSETPOINT_ON_REQUEST : std::uint32_t {
    // No request
    eDIS = 0,
    // Clock gate requested to be turned on
    eENABLE = 1,
  };

  enum class eSETPOINT_ON_DONE : std::uint32_t {
    // Clock gate is not turned on
    eDIS = 0,
    // Clock gate is turned on
    eENABLE = 1,
  };
  // Domain0 Low Power Mode
  using CPU0_MODE = ftl::mmio::Field<2, 0, eCPU0_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain0 request enter Low Power Mode
  using CPU0_MODE_REQUEST = ftl::mmio::Field<1, 2, eCPU0_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain0 Low Power Mode task done
  using CPU0_MODE_DONE = ftl::mmio::Field<1, 3, eCPU0_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain1 Low Power Mode
  using CPU1_MODE = ftl::mmio::Field<2, 4, eCPU1_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain1 request enter Low Power Mode
  using CPU1_MODE_REQUEST = ftl::mmio::Field<1, 6, eCPU1_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain1 Low Power Mode task done
  using CPU1_MODE_DONE = ftl::mmio::Field<1, 7, eCPU1_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain2 Low Power Mode
  using CPU2_MODE = ftl::mmio::Field<2, 8, eCPU2_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain2 request enter Low Power Mode
  using CPU2_MODE_REQUEST = ftl::mmio::Field<1, 10, eCPU2_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain2 Low Power Mode task done
  using CPU2_MODE_DONE = ftl::mmio::Field<1, 11, eCPU2_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain3 Low Power Mode
  using CPU3_MODE = ftl::mmio::Field<2, 12, eCPU3_MODE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain3 request enter Low Power Mode
  using CPU3_MODE_REQUEST = ftl::mmio::Field<1, 14, eCPU3_MODE_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domain3 Low Power Mode task done
  using CPU3_MODE_DONE = ftl::mmio::Field<1, 15, eCPU3_MODE_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Next Setpoint to change to
  using TARGET_SETPOINT = ftl::mmio::Field<4, 16, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  // Current Setpoint
  using CURRENT_SETPOINT = ftl::mmio::Field<4, 20, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock gate turn off request from GPC Setpoint
  using SETPOINT_OFF_REQUEST = ftl::mmio::Field<1, 24, eSETPOINT_OFF_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock gate turn off finish from GPC Setpoint
  using SETPOINT_OFF_DONE = ftl::mmio::Field<1, 25, eSETPOINT_OFF_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock gate turn on request from GPC Setpoint
  using SETPOINT_ON_REQUEST = ftl::mmio::Field<1, 26, eSETPOINT_ON_REQUEST, ftl::mmio::RO, ftl::mmio::Normal>;
  // Clock gate turn on finish from GPC Setpoint
  using SETPOINT_ON_DONE = ftl::mmio::Field<1, 27, eSETPOINT_ON_DONE, ftl::mmio::RO, ftl::mmio::Normal>;
}  // namespace LPCG40_STATUS1_fields_

