  enum class eCPU0_MODE_DONE : std::uint32_t {
    // Clock is not gated
    eDIS = 0,
    // Clock is gated-off
    eENABLE = 1,
  };

  enum class eCPU1_MODE : std::uint32_t {
    // Run
    eRUN = 0,
    // Wait
    eWAIT = 1,
    // Stop
    eSTOP = 2,
    // Suspend
    eSUSPEND = 3,
  };

