// LPCG working status
namespace LPCG82_STATUS0_fields_ {

  enum class eON : std::uint32_t {
    // LPCG is OFF.
    eON_0 = 0,
    // LPCG is ON.
    eON_1 = 1,
  };

  enum class eACTIVE_DOMAIN : std::uint32_t {
    // Clock not owned by any domain
    eNO = 0,
    // Clock owned by Domain0
    eZERO = 1,
    // Clock owned by Domain1
    eTWO = 2,
    // Clock owned by Domain0 and Domain1
    eTHREE = 3,
    // Clock owned by Domain2
    eFOUR = 4,
    // Clock owned by Domain0 and Domain2
    eFIVE = 5,
    // Clock owned by Domain1 and Domain2
    eSIX = 6,
    // Clock owned by Domain0, Domain1 and Domain 2
    eSEVEN = 7,
    // Clock owned by Domain3
    eEIGHT = 8,
    // Clock owned by Domain0 and Domain3
    eNINE = 9,
    // Clock owned by Domain1 and Domain3
    eTEN = 10,
    // Clock owned by Domain2 and Domain3
    eELV = 11,
    // Clock owned by Domain0, Domain 1, and Domain3
    eTW = 12,
    // Clock owned by Domain0, Domain 2, and Domain3
    eTH = 13,
    // Clock owned by Domain1, Domain 2, and Domain3
    eFR = 14,
    // Clock owned by all domains
    eall = 15,
  };

  enum class eDOMAIN_ENABLE : std::uint32_t {
    // No domain request
    eNO = 0,
    // Request from Domain0
    eZERO = 1,
    // Request from Domain1
    eTWO = 2,
    // Request from Domain0 and Domain1
    eTHREE = 3,
    // Request from Domain2
    eFOUR = 4,
    // Request from Domain0 and Domain2
    eFIVE = 5,
    // Request from Domain1 and Domain2
    eSIX = 6,
    // Request from Domain0, Domain1 and Domain 2
    eSEVEN = 7,
    // Request from Domain3
    eEIGHT = 8,
    // Request from Domain0 and Domain3
    eNINE = 9,
    // Request from Domain1 and Domain3
    eTEN = 10,
    // Request from Domain2 and Domain3
    eELV = 11,
    // Request from Domain0, Domain 1, and Domain3
    eTW = 12,
    // Request from Domain0, Domain 2, and Domain3
    eTH = 13,
    // Request from Domain1, Domain 2, and Domain3
    eFR = 14,
    // Request from all domains
    eall = 15,
  };
  // LPCG current state
  using ON = ftl::mmio::Field<1, 0, eON, ftl::mmio::RO, ftl::mmio::Normal>;
  // Domains that own this clock gate
  using ACTIVE_DOMAIN = ftl::mmio::Field<4, 8, eACTIVE_DOMAIN, ftl::mmio::RO, ftl::mmio::Normal>;
  // Enable status from each domain
  using DOMAIN_ENABLE = ftl::mmio::Field<4, 12, eDOMAIN_ENABLE, ftl::mmio::RO, ftl::mmio::Normal>;
}  // namespace LPCG82_STATUS0_fields_

