  using eDOMAIN_MODE = LPCG99_AUTHEN_fields_::eDOMAIN_MODE;
  using eSETPOINT_MODE = LPCG99_AUTHEN_fields_::eSETPOINT_MODE;
  using eCPULPM = LPCG99_AUTHEN_fields_::eCPULPM;
  using eLOCK_MODE = LPCG99_AUTHEN_fields_::eLOCK_MODE;
  using TZ_USER = LPCG99_AUTHEN_fields_::TZ_USER;
  using TZ_NS = LPCG99_AUTHEN_fields_::TZ_NS;
  using LOCK_TZ = LPCG99_AUTHEN_fields_::LOCK_TZ;
  using WHITE_LIST = LPCG99_AUTHEN_fields_::WHITE_LIST;
