  using DOMAIN_MODE = LPCG99_AUTHEN_fields_::DOMAIN_MODE;
  using SETPOINT_MODE = LPCG99_AUTHEN_fields_::SETPOINT_MODE;
  using CPULPM = LPCG99_AUTHEN_fields_::CPULPM;
  using LOCK_MODE = LPCG99_AUTHEN_fields_::LOCK_MODE;
