  using eLEVEL1 = LPCG100_DOMAIN_fields_::eLEVEL1;
  using eLEVEL2 = LPCG100_DOMAIN_fields_::eLEVEL2;
  using eLEVEL3 = LPCG100_DOMAIN_fields_::eLEVEL3;
