  using TZ_USER = ftl::mmio::Field<1, 0, eTZ_USER, ftl::mmio::RW, ftl::mmio::Normal>;
  // Non-secure access
  using TZ_NS = ftl::mmio::Field<1, 1, eTZ_NS, ftl::mmio::RW, ftl::mmio::Normal>;
